import matplotlib.pyplot as pltfrom sys import stdoutfrom models import henonfrom mpmath import mpimport osimport csvmp.dps = 19####  Фазовый портрет динамической системы###a = mp.mpf('1.43')b = mp.mpf('0.5')c = mp.mpf('-1.7594137')x = [mp.mpf('0.1'), mp.mpf('0.1'), mp.mpf('0.1')]# Списки для данных (храним как mpmath, конвертируем при записи)fase_port_0 = []  # полный портретfase_port_1 = []  # увеличение 1fase_port_2 = []  # увеличение 2# Транзиентprint("Транзиент...")for i in range(1_000_000):    x = henon(x, a, b, c)# Основной циклn = M = k = 0while k != 100:    stdout.write("\r%d" % k)    stdout.flush()    x = henon(x, a, b, c)    # Полный портрет    fase_port_0.append((x[0], x[1], x[2]))    n += 1    if (-0.38 < x[0] < -0.36) and (-0.414 < x[1] < -0.405):        fase_port_1.append((x[0], x[1], x[2]))        M += 1    if (-0.381 < x[0] < -0.378) and (-0.4088 < x[1] < -0.408):        fase_port_2.append((x[0], x[1], x[2]))        k += 1print('\n', n, M, k, sep='\n')# --- СОХРАНЕНИЕ В CSV ---output_dir = 'Portraits'os.makedirs(output_dir, exist_ok=True)print(f"📁 Данные будут сохранены в: {os.path.abspath(output_dir)}")# Заменяем точки и минусы, чтобы имя было безопасным для файловой системыdef safe_num(val, digits):    """Форматирует число и заменяет '.' и '-' на '_' и 'm'."""    s = f"{float(val):.{digits}f}"    return s.replace('.', 'p').replace('-', 'm')params_str = (    f"a{safe_num(a, 3)}"    f"_b{safe_num(b, 1)}"    f"_c{safe_num(c, 4)}"    f"_dps{mp.dps}")def save_to_csv(data, filepath, params=None):    """    Сохраняет список кортежей (x, y, z) в CSV.    params — словарь с параметрами системы (запишется в шапку как комментарий).    """    with open(filepath, 'w', newline='') as f:        # Пишем параметры как комментарии (начинаются с #)        if params:            for key, val in params.items():                f.write(f"# {key} = {val}\n")        # Заголовок        f.write("x,y,z\n")        # Данные        writer = csv.writer(f)        for xi, yi, zi in data:            writer.writerow([float(xi), float(yi), float(zi)])params = {'a': a, 'b': b, 'c': c, 'mp.dps': mp.dps}# Имена файлов с количеством точекfiles = [    (fase_port_0, f"phase_full_{params_str}_n{len(fase_port_0)}.csv"),    (fase_port_1, f"phase_zoom1_{params_str}_M{len(fase_port_1)}.csv"),    (fase_port_2, f"phase_zoom2_{params_str}_k{len(fase_port_2)}.csv"),]for data, filename in files:    if not data:        print(f"⚠️ Пропускаем пустой набор: {filename}")        continue    filepath = os.path.join(output_dir, filename)    save_to_csv(data, filepath, params)    print(f"✅ Сохранён: {filename} ({len(data)} точек)")print(f"\n🎉 Все CSV сохранены в: {os.path.abspath(output_dir)}")